from pathlib import Path
import requests,json,xml.sax.saxutils as X
R=Path(__file__).resolve().parents[1]
auth=json.load(open(R/'.secrets/lab-auth.json'));s=requests.Session();s.trust_env=False;s.auth=('labadmin',auth['jenkins_admin_password']);base='http://127.0.0.1:18981'
c=s.get(base+'/crumbIssuer/api/json').json();s.headers[c['crumbRequestField']]=c['crumb']
shell='''set -eu\nrm -rf source\ngit clone --no-hardlinks /lab/fixture source\ncd source\ngit checkout "$SHA"\npython3 -m unittest discover -s tests -v\ngit archive HEAD | sha256sum | tee ../artifact-digest.txt\n'''
config='''<project><actions/><description>Synthetic embargo CI; no real vulnerability or production secret.</description><keepDependencies>false</keepDependencies><properties><hudson.model.ParametersDefinitionProperty><parameterDefinitions><hudson.model.StringParameterDefinition><name>SHA</name><defaultValue>main</defaultValue></hudson.model.StringParameterDefinition></parameterDefinitions></hudson.model.ParametersDefinitionProperty></properties><scm class="hudson.scm.NullSCM"/><canRoam>true</canRoam><disabled>false</disabled><blockBuildWhenDownstreamBuilding>false</blockBuildWhenDownstreamBuilding><blockBuildWhenUpstreamBuilding>false</blockBuildWhenUpstreamBuilding><triggers/><concurrentBuild>false</concurrentBuild><builders><hudson.tasks.Shell><command>'''+X.escape(shell)+'''</command></hudson.tasks.Shell></builders><publishers><hudson.tasks.ArtifactArchiver><artifacts>artifact-digest.txt</artifacts><allowEmptyArchive>false</allowEmptyArchive><fingerprint>true</fingerprint></hudson.tasks.ArtifactArchiver></publishers><buildWrappers/></project>'''
r=s.post(base+'/createItem?name=synthetic-embargo',data=config,headers={'Content-Type':'application/xml'});print('Create isolated Jenkins job:',r.status_code);r.raise_for_status();(R/'jenkins-job-config.xml').write_text(config)
x=s.get(base+'/job/synthetic-embargo/api/json').json();(R/'jenkins-job-receipt.json').write_text(json.dumps({'status':r.status_code,'url':x['url']},indent=2))
